"""Concrete situations for every lesson and every practice representation."""

def topic_contexts(D):
 # Each group explicitly names the thing, where it is, the task, and the action.
 groups=[
 ([1], 'A private report stored as an encrypted file.', 'A laptop’s storage drive and the application opening the file.', 'Let authorized people recover the report while protecting it from unauthorized reading.', 'Encryption transforms the contents into ciphertext; the appropriate decryption procedure and key recover plaintext.'),
 ([2], 'A stolen student login, address, and medical information.', 'Account records and private files accessed through a compromised account.', 'Understand why personal information is valuable even without payment-card details.', 'An attacker may use stolen information for impersonation, fraud, resale, or extortion.'),
 ([3,31], 'A staff member enters a test password into a cloned login page.', 'The employee’s browser and a credential-collection page in the authorized lab.', 'Understand how a convincing page can obtain credentials through user interaction.', 'The form submits the entered information to the collecting system. This alone does not prove malicious code ran on the employee’s computer.'),
 ([4], 'A compromised workstation starts a command connection to an outside controller.', 'A program on the workstation and its outbound network connection.', 'Understand remote command access and why outbound traffic needs appropriate controls.', 'A reverse shell starts its connection from the affected computer. Filtering depends on rules, protocol handling, and visibility.'),
 ([5,43], 'A computer looks up a mail server, sends a message, and retrieves mail.', 'The client, DNS service, mail servers, and network connections.', 'Distinguish the communication jobs performed by different protocols.', 'DNS looks up names; SMTP transfers mail; POP retrieves mail. TCP/IP is a family of cooperating protocols.'),
 ([6,51], 'An organization hires staff to design security, configure tools, and supervise the team.', 'The organization’s security department and its supported systems.', 'Match a job’s actual duties to the textbook’s role definitions.', 'The administrator designs solutions for users, the technician configures and troubleshoots tools, and the manager supervises personnel.'),
 ([7], 'Two checkout requests both try to buy the last item in stock.', 'Concurrent operations in the store’s application and shared stock record.', 'Prevent conflicting operations from producing an unintended result.', 'If both requests read the old stock value before either updates it, timing can cause an incorrect result. Safe synchronization or transactions address the race.'),
 ([8], 'A caller pretends to be campus IT and asks for a login code.', 'A phone call or voice message received by an employee.', 'Recognize voice-based deception and verify identity through a trusted channel.', 'Vishing uses voice to manipulate the recipient. A displayed caller number can be spoofed and is not proof of identity.'),
 ([9,69], 'An email claims the recipient must urgently reset a university password.', 'The received message, full headers, links, and mail-system records.', 'Investigate the claimed sender and request without trusting the display name.', 'Compare routing and authentication evidence, sender domains, timing, and the request with a trusted reporting or verification process.'),
 ([10,36,73,74], 'An analyst examines a suspicious web page and its scripts.', 'Page source, an isolated test browser, and website-analysis services.', 'Determine what the page does and interpret the evidence behind a safety rating.', 'Static analysis inspects without executing; dynamic analysis observes execution. Manual and automated describe who performs the work; reputation summarizes observations.'),
 ([11,42,77], 'A laptop sends file data to a server across a network.', 'The application, transport service, IP network, and local links.', 'Understand which layer handles reliable delivery, separate messages, and forwarding.', 'TCP delivers an ordered byte stream with recovery; UDP provides separate datagrams without those guarantees; IP forwards packets toward destinations.'),
 ([12,26,67], 'A monitoring system warns about a network transfer that may be an attack or a legitimate backup.', 'The security alert and the network or host activity that triggered it.', 'Decide whether the alert represents a real problem and choose an appropriate response.', 'IDS alerts; IPS can intervene. Investigated evidence helps tune rules without hiding real attacks or unnecessarily blocking normal work.'),
 ([13], 'A malicious program on an infected computer waits for remote instructions.', 'The infected device and a command-and-control server.', 'Recognize the program’s remote-control role.', 'A bot receives C2 commands. A botnet is a collection of controlled devices; a logic bomb is classified by activation on a specified condition.'),
 ([14,76], 'Two groups follow different rules for accepting blockchain records, or two payments try to spend the same funds.', 'The transaction ledger maintained by participating computers.', 'Understand agreement about which valid transaction history is accepted.', 'Validation and consensus resolve competing histories. Incompatible rule changes can produce a hard fork when participants continue separate histories.'),
 ([15], 'A network segment may have been corrupted during transmission.', 'The transmitted data and the receiver’s error-checking calculation.', 'Detect accidental changes to the received contents.', 'The receiver recalculates a checksum and compares it with the transmitted value. An ordinary checksum does not authenticate the sender against deliberate changes.'),
 ([16,71], 'An IT team must install security updates on many company computers without breaking work.', 'Update distribution, test devices, deployment records, and production systems.', 'Repair weaknesses efficiently while verifying that needed services still work.', 'Bandwidth helps distribute updates; centralized services coordinate; analytics prioritizes; virtual machines support testing. Stage changes and verify the results.'),
 ([17], 'An employee opens an infected program or document, or a malicious program spreads between computers.', 'Program files, documents, running software, and networked devices.', 'Identify how malicious software propagates and what harmful behavior it performs.', 'A virus attaches to a host; a worm propagates independently. Spyware observes, adware displays ads, scareware deceives with warnings, and a backdoor provides concealed access.'),
 ([18,37], 'A business sends a private document and needs to detect changes or verify its approval.', 'The document, any encrypted representation, its computed digest, and any digital signature.', 'Choose the operation that fits confidentiality, content comparison, or origin verification.', 'Encryption hides readable content; a trusted hash comparison checks content; a signature supports verification under a trusted signing key. These operations are not interchangeable.'),
 ([19,57], 'A downloaded file is compared with a publisher’s trusted reference digest.', 'The file’s bytes and a program computing a digest from those bytes.', 'Detect different contents using a trusted comparison, and distinguish that from sender authentication.', 'A secure hash computes a fixed-length digest. Collisions remain possible but should be hard to find. HMAC additionally uses a shared secret for message authentication.'),
 ([20,21,41], 'A user transfers digital value to another user without a central ledger operator.', 'Transactions and blocks validated by participating Bitcoin computers.', 'Authorize spending, prevent conflicting accepted spends, and maintain an agreed history.', 'Keys authorize spending through signatures; nodes validate transactions; consensus establishes accepted history; incentives support block production.'),
 ([22,47,48,52], 'A school stores private student records and operates a registration service.', 'The records, accounts, applications, and computers used by students and staff.', 'Protect privacy, accurate records, and usable services while assessing likely harm.', 'Identify valuable assets, weaknesses, possible threats, and likelihood and impact. Reduce, avoid, accept, or transfer risk according to the action taken.'),
 ([23,50], 'A company considers both a malicious employee and an outside criminal group.', 'The organization’s accounts, information, services, and existing access.', 'Assess what each actor could reach, why they might act, and what resources they have.', 'Compare motivation, capability, resources, and access instead of assuming every attacker has the same opportunities.'),
 ([24,25,49], 'A store separates payment computers, checks incoming traffic, records device activity, and provides backup network equipment.', 'Network boundaries, staff computers, security records, and the people managing controls.', 'Keep the business operating while restricting harmful actions at multiple points.', 'Layer complementary controls, grant necessary access only, collect useful evidence, and plan for growth and device failure. People and procedures must support the tools.'),
 ([27,81], 'An analyst needs evidence about traffic leaving a company laptop.', 'A monitored network link, packet captures, connection summaries, and proxy records.', 'Choose evidence that can answer who communicated, when, how much, and potentially what was carried.', 'PCAP records observed packet bytes; flow records summarize connections. Mirrors and taps determine what the sensor can see. A proxy handles requests; allowlisting controls software execution.'),
 ([28], 'Customers cannot use a website because an attacker occupies its connection-handling capacity.', 'The web server and the network or application connections it handles.', 'Keep the service usable for legitimate customers.', 'SYN floods target connection setup; Slowloris holds web requests incomplete. Match mitigation to the exhausted resource rather than assuming every attack needs enormous bandwidth.'),
 ([29], 'A website accepts user input, queries a database, and displays results in a browser.', 'The application, database query, browser output, and potentially the program’s memory.', 'Keep input from becoming unintended instructions at the relevant interpreter or memory boundary.', 'Parameterized queries address SQL injection; safe output handling addresses XSS; bounds checking and memory safety address buffer overflows. The flaws affect different places.'),
 ([30,68], 'A person receives a convincing message promising a reward, or a website’s visible page is changed without permission.', 'Email, text messages, calls, payment requests, or published website content.', 'Distinguish manipulation of people from unauthorized changes to website content.', 'Social-engineering categories depend on targeting and delivery channel. Advance-fee fraud asks for payment first; defacement changes the visible site.'),
 ([32], 'An employee types a password on a computer with a software or hardware keylogger.', 'The device’s input path, before transport encryption protects a web connection.', 'Understand how information can be captured at the device even when HTTPS is used.', 'A keylogger records keystrokes. Transport encryption does not protect input already observed on a compromised endpoint; physical and software controls address different variants.'),
 ([33,72], 'An administrator configures a staff laptop before allowing normal work and network access.', 'The device’s accounts, operating-system settings, services, updates, and local security controls.', 'Reduce unnecessary exposure and enforce appropriate access and execution rules.', 'Use standard accounts, patch software, disable unneeded services, configure host protections, and verify required settings. NAC, GPO, endpoint firewalls, and HIPS perform different jobs.'),
 ([34,82], 'A staff login is followed by an unusual program launch and an outbound transfer.', 'Account logs, endpoint process and file events, and network records.', 'Reconstruct related events, assess affected systems, and decide containment actions.', 'Correlate timestamps and details rather than assuming one alert proves all data was stolen. Check clock accuracy, record coverage, and how long logs were retained.'),
 ([35,83], 'A student runs intentionally vulnerable guest machines for a controlled lab.', 'Virtualization software, guest operating systems, virtual network adapters, and saved states.', 'Keep experiments controlled and distinguish the guest environment from the physical host.', 'Hypervisors manage guests; network settings affect reachability; snapshots help restore states. Containers, VDI, and uncontrolled VM growth have different boundaries and management concerns.'),
 ([38,59,60,61], 'Alice sends Bob a confidential document and may also sign it.', 'Alice’s and Bob’s applications, cryptographic keys, the document, and any signature.', 'Keep the contents readable by the intended recipient and independently verify signed content.', 'Public-key encryption for Bob uses Bob’s public key and corresponding private decryption key. Alice signs with her private signing key; verification uses her trusted public key. Hybrid systems combine public-key techniques with symmetric data protection.'),
 ([39], 'A classroom program encrypts and decrypts a small integer using a toy RSA example.', 'The program’s selected primes, modulus, exponents, and modular calculations.', 'Understand the mathematical relationship between public and private exponents.', 'Choose e coprime to φ(n), and d so ed leaves remainder one modulo φ(n). The small unpadded example teaches arithmetic and is not suitable for real confidential data.'),
 ([40,75], 'A block records transactions and points to earlier blockchain history.', 'Transaction hashes, the Merkle tree, block-header fields, and the previous-block hash.', 'Summarize included transactions and make changes to linked history detectable.', 'A Merkle root commits to transactions; a proof checks inclusion under that root. The previous-block hash links history; a proof-of-work nonce is varied during the mining search.'),
 ([44], 'A traveler sees a wireless network name that looks like the hotel’s network.', 'The Wi-Fi selection screen, access point, and any captive login page.', 'Avoid treating a copied name or convincing page as proof of a trusted operator.', 'Displayed names and identifiers can be spoofed. Verify the intended network and service rather than relying on the familiar label alone.'),
 ([45,53,63], 'A laptop holds sensitive files, and some may be open in applications.', 'Stored drive data, files in working memory, and key-protection components.', 'Match protection to stored data, traveling data, or data currently being used.', 'File or disk encryption protects selected stored contents. TPM and HSM protect particular keys and operations. An unlocked application can still expose readable information.'),
 ([46], 'A company discovers an unpatched server, an unsafe setting, and a fraudulent payment request.', 'Software, device configuration, limited system resources, and business procedures.', 'Identify which kind of weakness permits each kind of harm.', 'Patching repairs software flaws; secure settings restrict exposure; capacity controls address exhaustion; verification procedures address deceptive business requests.'),
 ([54,55,56,58], 'A program processes a message using a cryptographic construction.', 'The message data, procedure, key material, and internal processing steps.', 'Distinguish processing rules and security requirements instead of treating every construction as the same.', 'Substitution replaces symbols; XOR combines bits; block and stream ciphers process data differently. Secure randomness, correct key use, confusion, and diffusion have distinct roles; a true one-time pad is never reused.'),
 ([62,64], 'A device must protect communication while operating with limited memory, power, and response time.', 'The implemented protocol, algorithm, software, and device resources.', 'Provide appropriate security without ignoring implementation errors or operating limits.', 'Weak algorithms, forced weaker settings, and programming mistakes create different problems. Resource limits affect implementation choices but do not justify assuming insecure choices are safe.'),
 ([65], 'Industrial equipment reports apparently normal readings while targeted malware interferes with operations.', 'Control equipment, associated computers, and the monitoring information they provide.', 'Recognize that compromised components can produce misleading observations.', 'The Stuxnet example connects targeted compromise with deceptive monitoring. Independent evidence and appropriate system boundaries matter.'),
 ([66,78], 'A company wants to deny an address, block website categories, and prevent unapproved programs from running.', 'Network rules, application intermediaries, and endpoint execution policy.', 'Choose enforcement at the place where the unwanted action happens.', 'Firewall or ACL rules can block traffic attributes; proxies can enforce application policies; application allowlisting restricts execution. Merely observing an event is not the same as preventing it.'),
 ([70], 'A pop-up claims the computer is infected or the drive is failing and demands payment or installation.', 'An employee’s screen and the source of the warning.', 'Verify the claim without following an attacker’s instructions.', 'Use known trusted security tools and support channels. A professional appearance and urgent wording do not establish that a warning is legitimate.'),
 ([79,80], 'An administrator selects services for web access, file transfer, email, device management, and clock synchronization.', 'Clients, servers, protocol configuration, and communication paths.', 'Choose the correct service and verify what protection is actually provided.', 'HTTPS, FTPS, SFTP, S/MIME, and SRTP protect different applications. DNS, SNMP, ICMP, and NTP have distinct jobs; their ordinary names do not guarantee every security property.'),
 ([84], 'A business uses a provider’s hosted application, platform, or virtual server.', 'The provider’s infrastructure and the customer’s applications, accounts, data, and configuration.', 'Determine which security work belongs to the provider and which still belongs to the customer.', 'SaaS supplies an application; PaaS supplies a platform; IaaS supplies infrastructure. Responsibilities depend on the service arrangement and do not disappear when moving to the cloud.'),
 ]
 mapped={}
 D['topicOrientation']=[]
 for i,(numbers,obj,location,purpose,action) in enumerate(groups,1):
  context=dict(object=obj,location=location,purpose=purpose,action=action)
  for n in numbers:
   assert n not in mapped,n
   mapped[n]=context
  n=numbers[0];id=f'425-topic-context-{i}'
  # A concrete task-recognition check comes before the related application.
  others=[g[3] for g in groups if g[3]!=purpose][:3]
  D['topicOrientation'].append(dict(id=id,source=n,section=D['questions'][n-1]['section'],q=obj+' What is the security task in this situation?',correct=purpose,distractors=others,teach=action,answer=action,example=obj+' '+location,foundation=True,topicOrientation=True,format='mc',setting=context,preparingFor=D['questions'][n-1]['title']))
  D['prerequisites'][id]=[]
  for qn in numbers:D['questions'][qn-1]['topicIntroId']=id
 assert set(mapped)==set(range(1,85))
 D['topicContexts']={str(n):v for n,v in mapped.items()}
 # Existing term-specific encryption/hash contexts stay more specific than the
 # source lesson where a term was first introduced.
 crypto_terms=['key','encrypt','cipher','plaintext','hash','digest','sha-256','signature','collision']
 pools=['questions','checks','vocab','foundations','trueFalse','cloze','sorts','discussions']
 for pool in pools:
  for x in D[pool]:
   n=x.get('number',x.get('source'));context=mapped[n]
   term=x.get('term','').lower()
   if term and any(t in term for t in crypto_terms):context=D['practicalContexts'][x['contextKey']]
   x['setting']=dict(context)
   # The item's own concrete example remains visible, rather than hiding it
   # behind answer feedback. It supplements the lesson-level location and task.
   x['setting']['example']=x.get('example',D['questions'][n-1]['example'])
   x['topicIntroId']=D['questions'][n-1]['topicIntroId']
 D['counts']['topicOrientation']=len(D['topicOrientation'])
